
CREATE TABLE IF NOT EXISTS roles(id BIGSERIAL PRIMARY KEY,nombre TEXT NOT NULL UNIQUE,descripcion TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Activo' CHECK(estado IN ('Activo','Inactivo')));
CREATE TABLE IF NOT EXISTS usuarios(id BIGSERIAL PRIMARY KEY,rol_id BIGINT NOT NULL REFERENCES roles(id),nombre TEXT NOT NULL,usuario TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Activo' CHECK(estado IN ('Activo','Inactivo')),ultimo_acceso TEXT);
CREATE TABLE IF NOT EXISTS permisos(id BIGSERIAL PRIMARY KEY,codigo TEXT NOT NULL UNIQUE,descripcion TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roles_permisos(id BIGSERIAL PRIMARY KEY,rol_id BIGINT NOT NULL REFERENCES roles(id),permiso_id BIGINT NOT NULL REFERENCES permisos(id),UNIQUE(rol_id,permiso_id));
CREATE TABLE IF NOT EXISTS sesiones(token_hash TEXT PRIMARY KEY,usuario_id BIGINT NOT NULL REFERENCES usuarios(id),expira TEXT NOT NULL,csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clientes(id BIGSERIAL PRIMARY KEY,usuario_id BIGINT UNIQUE REFERENCES usuarios(id),nombre TEXT NOT NULL,telefono TEXT NOT NULL,direccion TEXT NOT NULL,referencia TEXT,estado TEXT NOT NULL DEFAULT 'Activo',correo TEXT,fecha_registro TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categorias(id BIGSERIAL PRIMARY KEY,nombre TEXT NOT NULL UNIQUE,descripcion TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Activo');
CREATE TABLE IF NOT EXISTS productos(id BIGSERIAL PRIMARY KEY,categoria_id BIGINT NOT NULL REFERENCES categorias(id),sku TEXT NOT NULL UNIQUE,nombre TEXT NOT NULL,descripcion TEXT NOT NULL,ancho_cm TEXT NOT NULL,largo_cm TEXT NOT NULL,precio_actual BIGINT NOT NULL CHECK(precio_actual>0),imagen_url TEXT,estado TEXT NOT NULL DEFAULT 'Activo');
CREATE TABLE IF NOT EXISTS existencias(id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL UNIQUE REFERENCES productos(id),stock_fisico BIGINT NOT NULL DEFAULT 0 CHECK(stock_fisico>=0),stock_minimo BIGINT NOT NULL DEFAULT 2 CHECK(stock_minimo>=0),version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pedidos(id BIGSERIAL PRIMARY KEY,cliente_id BIGINT NOT NULL REFERENCES clientes(id),creador_id BIGINT NOT NULL REFERENCES usuarios(id),numero TEXT NOT NULL UNIQUE,canal TEXT NOT NULL CHECK(canal IN ('TikTok','WhatsApp','Directo')),direccion_entrega TEXT NOT NULL,referencia_entrega TEXT,estado TEXT NOT NULL CHECK(estado IN ('Pendiente stock','Reservado','Confirmado','Cancelado','Entregado')),fecha TEXT NOT NULL,motivo_cancelacion TEXT);
CREATE TABLE IF NOT EXISTS detalles_pedido(id BIGSERIAL PRIMARY KEY,pedido_id BIGINT NOT NULL REFERENCES pedidos(id),producto_id BIGINT NOT NULL REFERENCES productos(id),cantidad BIGINT NOT NULL CHECK(cantidad>0),precio_unitario BIGINT NOT NULL CHECK(precio_unitario>0),UNIQUE(pedido_id,producto_id));
CREATE TABLE IF NOT EXISTS reservas(id BIGSERIAL PRIMARY KEY,detalle_pedido_id BIGINT NOT NULL UNIQUE REFERENCES detalles_pedido(id),cantidad BIGINT NOT NULL CHECK(cantidad>0),estado TEXT NOT NULL CHECK(estado IN ('Vigente','Consumida','Liberada')),fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ventas(id BIGSERIAL PRIMARY KEY,cliente_id BIGINT NOT NULL REFERENCES clientes(id),pedido_id BIGINT UNIQUE REFERENCES pedidos(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),numero TEXT NOT NULL UNIQUE,fecha TEXT NOT NULL,estado TEXT NOT NULL CHECK(estado IN ('Vigente','Anulada')),motivo_anulacion TEXT,evidencia_devolucion TEXT);
CREATE TABLE IF NOT EXISTS detalles_venta(id BIGSERIAL PRIMARY KEY,venta_id BIGINT NOT NULL REFERENCES ventas(id),producto_id BIGINT NOT NULL REFERENCES productos(id),cantidad BIGINT NOT NULL CHECK(cantidad>0),precio_unitario BIGINT NOT NULL CHECK(precio_unitario>0),UNIQUE(venta_id,producto_id));
CREATE TABLE IF NOT EXISTS proveedores(id BIGSERIAL PRIMARY KEY,nombre TEXT NOT NULL,identificacion TEXT UNIQUE,telefono TEXT NOT NULL,direccion TEXT NOT NULL,representante TEXT,rubro TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Activo',disponibilidad TEXT);
CREATE TABLE IF NOT EXISTS compras(id BIGSERIAL PRIMARY KEY,proveedor_id BIGINT NOT NULL REFERENCES proveedores(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),referencia TEXT NOT NULL,fecha TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Recibida' CHECK(estado='Recibida'),observacion TEXT,UNIQUE(proveedor_id,referencia));
CREATE TABLE IF NOT EXISTS detalles_compra(id BIGSERIAL PRIMARY KEY,compra_id BIGINT NOT NULL REFERENCES compras(id),producto_id BIGINT NOT NULL REFERENCES productos(id),cantidad BIGINT NOT NULL CHECK(cantidad>0),costo_unitario BIGINT NOT NULL CHECK(costo_unitario>0),UNIQUE(compra_id,producto_id));
CREATE TABLE IF NOT EXISTS ajustes_inventario(id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),variacion BIGINT NOT NULL CHECK(variacion<>0),motivo TEXT NOT NULL,evidencia_url TEXT,fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS movimientos_inventario(id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),detalle_compra_id BIGINT UNIQUE REFERENCES detalles_compra(id),detalle_venta_id BIGINT REFERENCES detalles_venta(id),ajuste_id BIGINT UNIQUE REFERENCES ajustes_inventario(id),variacion BIGINT NOT NULL CHECK(variacion<>0),saldo_resultante BIGINT NOT NULL CHECK(saldo_resultante>=0),tipo TEXT NOT NULL CHECK(tipo IN ('Compra','Venta','Reversion venta','Ajuste','Apertura')),fecha TEXT NOT NULL,CHECK((CASE WHEN detalle_compra_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN detalle_venta_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN ajuste_id IS NOT NULL THEN 1 ELSE 0 END)=1),UNIQUE(detalle_venta_id,tipo));
CREATE TABLE IF NOT EXISTS alertas_stock(id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos(id),estado TEXT NOT NULL CHECK(estado IN ('Activa','Resuelta')),fecha_apertura TEXT NOT NULL,fecha_resolucion TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS alerta_activa ON alertas_stock(producto_id) WHERE estado='Activa';
CREATE TABLE IF NOT EXISTS pagos(id BIGSERIAL PRIMARY KEY,pedido_id BIGINT REFERENCES pedidos(id),venta_id BIGINT REFERENCES ventas(id),registrador_id BIGINT NOT NULL REFERENCES usuarios(id),verificador_id BIGINT REFERENCES usuarios(id),monto BIGINT NOT NULL CHECK(monto>0),metodo TEXT NOT NULL CHECK(metodo IN ('Efectivo','Transferencia','QR')),referencia TEXT NOT NULL UNIQUE,evidencia_url TEXT,estado TEXT NOT NULL CHECK(estado IN ('Pendiente verificacion','Verificado','Rechazado','Anulado')),fecha TEXT NOT NULL,fecha_verificacion TEXT,motivo TEXT,CHECK((CASE WHEN pedido_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN venta_id IS NOT NULL THEN 1 ELSE 0 END)=1));
CREATE TABLE IF NOT EXISTS ingresos(id BIGSERIAL PRIMARY KEY,pago_id BIGINT NOT NULL UNIQUE REFERENCES pagos(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),fecha_registro TEXT NOT NULL,estado TEXT NOT NULL CHECK(estado IN ('Vigente','Anulado')));
CREATE TABLE IF NOT EXISTS comprobantes_pago(id BIGSERIAL PRIMARY KEY,pago_id BIGINT NOT NULL UNIQUE REFERENCES pagos(id),numero TEXT NOT NULL UNIQUE,fecha_emision TEXT NOT NULL,archivo_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transportistas(id BIGSERIAL PRIMARY KEY,nombre TEXT NOT NULL,telefono TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Disponible' CHECK(estado IN ('Disponible','Inactivo')));
CREATE TABLE IF NOT EXISTS envios(id BIGSERIAL PRIMARY KEY,pedido_id BIGINT NOT NULL REFERENCES pedidos(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),numero TEXT NOT NULL UNIQUE,direccion TEXT NOT NULL,referencia TEXT,costo BIGINT NOT NULL CHECK(costo>=0),fecha_estimada TEXT,numero_guia TEXT,fecha_despacho TEXT,fecha_entrega TEXT,receptor TEXT,evidencia_entrega TEXT,estado TEXT NOT NULL CHECK(estado IN ('Preparado','En transito','Entregado','Cancelado')),observacion TEXT,incidencia TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS envio_activo ON envios(pedido_id) WHERE estado<>'Cancelado';
CREATE TABLE IF NOT EXISTS asignaciones_transporte(id BIGSERIAL PRIMARY KEY,envio_id BIGINT NOT NULL REFERENCES envios(id),transportista_id BIGINT NOT NULL REFERENCES transportistas(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),fecha TEXT NOT NULL,fecha_fin TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS asignacion_actual ON asignaciones_transporte(envio_id) WHERE fecha_fin IS NULL;
CREATE TABLE IF NOT EXISTS reclamos(id BIGSERIAL PRIMARY KEY,cliente_id BIGINT NOT NULL REFERENCES clientes(id),pedido_id BIGINT REFERENCES pedidos(id),venta_id BIGINT REFERENCES ventas(id),numero TEXT NOT NULL UNIQUE,motivo TEXT NOT NULL,descripcion TEXT NOT NULL,estado TEXT NOT NULL CHECK(estado IN ('Pendiente','En revision','Solucionado','Cerrado')),fecha TEXT NOT NULL,CHECK((CASE WHEN pedido_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN venta_id IS NOT NULL THEN 1 ELSE 0 END)=1));
CREATE TABLE IF NOT EXISTS historial_reclamos(id BIGSERIAL PRIMARY KEY,reclamo_id BIGINT NOT NULL REFERENCES reclamos(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),estado_anterior TEXT,estado_nuevo TEXT NOT NULL,observacion TEXT NOT NULL,fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS publicaciones(id BIGSERIAL PRIMARY KEY,responsable_id BIGINT NOT NULL REFERENCES usuarios(id),canal TEXT NOT NULL CHECK(canal IN ('Catalogo','TikTok','WhatsApp')),contenido TEXT NOT NULL,campania TEXT,material_url TEXT,enlace_externo TEXT,estado TEXT NOT NULL CHECK(estado IN ('Borrador','Preparada','Publicada')),fecha TEXT NOT NULL,fecha_publicacion TEXT);
CREATE TABLE IF NOT EXISTS publicaciones_productos(id BIGSERIAL PRIMARY KEY,publicacion_id BIGINT NOT NULL REFERENCES publicaciones(id),producto_id BIGINT NOT NULL REFERENCES productos(id),UNIQUE(publicacion_id,producto_id));
CREATE TABLE IF NOT EXISTS consultas_marketing(id BIGSERIAL PRIMARY KEY,cliente_id BIGINT REFERENCES clientes(id),publicacion_id BIGINT REFERENCES publicaciones(id),contacto TEXT NOT NULL,canal TEXT NOT NULL CHECK(canal IN ('TikTok','WhatsApp','Directo')),pregunta TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Pendiente' CHECK(estado IN ('Pendiente','Respondida')),fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS respuestas_consulta(id BIGSERIAL PRIMARY KEY,consulta_id BIGINT NOT NULL REFERENCES consultas_marketing(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),respuesta TEXT NOT NULL,estado TEXT NOT NULL CHECK(estado IN ('Preparada','Enviada')),evidencia TEXT,fecha TEXT NOT NULL,fecha_envio TEXT);
CREATE TABLE IF NOT EXISTS metricas_publicacion(id BIGSERIAL PRIMARY KEY,publicacion_id BIGINT NOT NULL REFERENCES publicaciones(id),indicador TEXT NOT NULL,valor BIGINT NOT NULL CHECK(valor>=0),fuente TEXT NOT NULL,fecha_medicion TEXT NOT NULL,UNIQUE(publicacion_id,indicador,fecha_medicion,fuente));
CREATE TABLE IF NOT EXISTS respaldos(id BIGSERIAL PRIMARY KEY,nombre TEXT NOT NULL,ubicacion TEXT NOT NULL UNIQUE,checksum TEXT NOT NULL,fecha TEXT NOT NULL,responsable_id BIGINT NOT NULL REFERENCES usuarios(id),estado TEXT NOT NULL DEFAULT 'Verificado' CHECK(estado IN ('En proceso','Verificado','Fallido')));
CREATE TABLE IF NOT EXISTS restauraciones(id BIGSERIAL PRIMARY KEY,respaldo_id BIGINT NOT NULL REFERENCES respaldos(id),responsable_id BIGINT NOT NULL REFERENCES usuarios(id),copia_previa_id BIGINT NOT NULL REFERENCES respaldos(id),estado TEXT NOT NULL CHECK(estado IN ('En proceso','Verificada','Fallida')),inicio TEXT NOT NULL,fin TEXT,resultado TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auditorias(id BIGSERIAL PRIMARY KEY,usuario_id BIGINT REFERENCES usuarios(id),entidad TEXT NOT NULL,registro_id BIGINT,accion TEXT NOT NULL,modulo TEXT NOT NULL,operacion TEXT NOT NULL,documento_id BIGINT,detalle TEXT NOT NULL,fecha TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS pagos_pedido ON pagos(pedido_id,estado);
CREATE INDEX IF NOT EXISTS pagos_venta ON pagos(venta_id,estado);
CREATE INDEX IF NOT EXISTS detalles_pedido_producto ON detalles_pedido(producto_id);
CREATE INDEX IF NOT EXISTS ventas_fecha ON ventas(fecha);
CREATE INDEX IF NOT EXISTS auditorias_fecha ON auditorias(fecha);

CREATE TABLE IF NOT EXISTS archivos_contenido(nombre TEXT PRIMARY KEY,contenido BYTEA NOT NULL,checksum TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS respaldos_contenido(nombre TEXT PRIMARY KEY,contenido BYTEA NOT NULL);
CREATE TABLE IF NOT EXISTS restauraciones_externas(id BIGSERIAL PRIMARY KEY,fecha TEXT NOT NULL,usuario TEXT NOT NULL,respaldo TEXT NOT NULL,resultado TEXT NOT NULL,copia_previa_id BIGINT);
